message.content:
{
  "gate_token": "lnNC-uV_mHzpZ5kCuDVqXA",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined royal city.",
      "visual_description": "A windswept overlook at dusk; broken spires and torn royal banners stretch to the horizon as a cartographer pins a fragile map to a stone.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp flickers a first warning.",
      "visual_description": "A close-up of a battered oil lamp on the map's corner, its single fiery eye glowing as shadows of cursed towers reach across the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peeks between the iron bars of an enormous, vine-strangled gate, its key-wind tail ticking.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver slips through a shattered window.",
      "visual_description": "A figure in a clear diving helmet glides headfirst through a jagged stained-glass window, the coat catching colored reflections of broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team regroups in a collapsed plaza.",
      "visual_description": "Cracked fountain at center; the cartographer, the lamp on a stone, the fox at her boots, and the diver climbing down from a window frame.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "They discover the sleeping tax collector slumped at his post.",
      "visual_description": "An official snoring on a toppled desk, ledger book as pillow, stamped papers clinging to his sleeves, oblivious to nearby distant fires.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The lamp warns of an armored patrol ahead.",
      "visual_description": "Narrow alley with the oracle lamp glowing bright red, casting long shadows of approaching armored figures around a corner (only shadows visible).",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox lures the patrol away with ticking footsteps.",
      "visual_description": "The clockwork fox sprints across rubble, sparks flying from its tail, while armored helmets (shown as silhouettes) clatter after it down a side street.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara charts a path around the cursed tower.",
      "visual_description": "A leaning black tower wreathed in violet mist; the cartographer crouches with her brass compass spinning wildly, ink running on wet parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a beast echo over rooftops.",
      "visual_description": "A massive scaly shadow passes across the moon above broken chimneys; the diver pulls the cartographer into the shelter of a doorway.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "They reach a sealed magic door.",
      "visual_description": "An arched door covered in shifting silver runes; the lamp's eye narrows as the diver presses a gloved palm to the cold metal surface.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox returns with a stolen key in its jaws.",
      "visual_description": "The clockwork fox trots out of fog with a heavy iron key clutched in tiny metal teeth, gears whirring proudly.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "The door opens onto a hall of mirrors.",
      "visual_description": "Endless tall mirrors line a ruined throne hall, each reflecting torn royal banners; the diver steps forward, reflections rippling like water.",
      "characters": ["glass_diver", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The diver swims through a mirror and finds the captive.",
      "visual_description": "Inside a silver-blue mirror-world, the diver reaches a chained figure (back to viewer) on a glass floor as the helmet glints with bubbles.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping tax collector wakes briefly and stamps the wrong paper.",
      "visual_description": "Outside the mirror hall, the official yawns, slamming a red stamp onto a map; ink splatters reveal a hidden escape route on the parchment.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The team races through alleys as alarms ring.",
      "visual_description": "Bells clang from a cracked belfry; the cartographer, lamp held high, sprints alongside the diver while the fox darts between their feet.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They reach the long bridge over the chasm.",
      "visual_description": "A narrow stone bridge stretches over a glowing red gorge; tattered royal banners flap from its broken arches as the team begins to cross.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Across the bridge, they look back at the burning city.",
      "visual_description": "On a green hillside at dawn, the cartographer folds her map, the diver's helmet steams, the fox's tail ticks slower, and the lamp's eye softens to gold.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

